Build lookup dictionaries from SH1 and RP1 keyed by stripped ID in column B with QTY in column C. For each row 2–11 in merging, look up column B in both dictionaries and write the QTY to C and D, using “-” for missing, blank, or error values. Save the workbook with only the answer cells changed.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def norm_key(v):
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v).strip()

def build_lookup(sheet_name):
    ws = vals[sheet_name]
    lookup = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        if len(row) < 3:
            continue
        id_val, qty_val = row[1], row[2]
        key = norm_key(id_val)
        if key == "":
            continue
        if key not in lookup:
            lookup[key] = qty_val
    return lookup

def clean_qty(v):
    if v is None:
        return "-"
    if isinstance(v, str):
        s = v.strip()
        if s == "" or s.startswith("#"):
            return "-"
        try:
            if "." in s:
                return float(s)
            return int(s)
        except ValueError:
            return s
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

sh1 = build_lookup("SH1")
rp1 = build_lookup("RP1")
ws = wb["merging"]

for r in range(2, 12):
    key = norm_key(ws.cell(row=r, column=2).value)
    c_val = clean_qty(sh1.get(key))
    d_val = clean_qty(rp1.get(key))
    ws.cell(row=r, column=3).value = c_val
    ws.cell(row=r, column=4).value = d_val

print("SH1 entries:", len(sh1), "RP1 entries:", len(rp1))
for r in range(2, 12):
    print(r, ws.cell(row=r, column=2).value, ws.cell(row=r, column=3).value, ws.cell(row=r, column=4).value)

wb.save(OUT)
